def test_builtins_round_int_ndigits_zero(self):
    def fn(x, i):
        return x + round(i, 0)

    cfn = torch.compile(fullgraph=True, dynamic=True)(fn)

    x = torch.zeros(2, device=self.device)
    i = 123

    with torch.no_grad():
        self.assertEqual(cfn(x, i), fn(x, i))

def test_silu(self):
